insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('6ea152ad-9b82-4f18-9b90-23c3246e18e8', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', null, 'topic'::public.curated_course_node_type, 'Religion as an Academic Object of Study', 'This opening section establishes the course''s non-devotional, non-sectarian frame. Students learn to study religion as a human, historical, social, textual, material, and experiential phenomenon while taking practitioners seriously.', 0),
  ('df2a9c1a-dcab-4b82-ad47-18af0dfc6d72', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '6ea152ad-9b82-4f18-9b90-23c3246e18e8', 'subtopic'::public.curated_course_node_type, 'Academic vs. confessional study', 'Students learn the difference between studying religion from within a tradition and analyzing religion with public, evidence-based academic tools.', 0),
  ('9612ff0f-f57e-4ffd-a606-6b13791bf3f6', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'df2a9c1a-dcab-4b82-ad47-18af0dfc6d72', 'concept'::public.curated_course_node_type, 'Theology, apologetics, and religious studies', null, 0),
  ('52d569a5-5e1c-4b35-bb16-95d33c84691f', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'df2a9c1a-dcab-4b82-ad47-18af0dfc6d72', 'concept'::public.curated_course_node_type, 'Insider and outsider perspectives', null, 1),
  ('2fbef32e-054f-4b49-802c-1d014b9ba0c9', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'df2a9c1a-dcab-4b82-ad47-18af0dfc6d72', 'concept'::public.curated_course_node_type, 'Description before evaluation', null, 2),
  ('f5e1fe7e-a413-4430-87e5-1ea120f548c9', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '6ea152ad-9b82-4f18-9b90-23c3246e18e8', 'subtopic'::public.curated_course_node_type, 'Religion in human life', 'The goal is to see religion as a force in meaning-making, identity, institutions, art, law, politics, conflict, and care.', 1),
  ('cfe4c778-76b6-4e42-a9e5-cae0e37205e1', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'f5e1fe7e-a413-4430-87e5-1ea120f548c9', 'concept'::public.curated_course_node_type, 'Belief and practice', null, 0),
  ('84dbc32d-abe0-4fe0-97e0-5a07fbf03268', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'f5e1fe7e-a413-4430-87e5-1ea120f548c9', 'concept'::public.curated_course_node_type, 'Identity and belonging', null, 1),
  ('7fa581bb-e983-4fda-8a34-56a1917317e2', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'f5e1fe7e-a413-4430-87e5-1ea120f548c9', 'concept'::public.curated_course_node_type, 'Public and private religion', null, 2),
  ('adfa65a6-1228-496f-90ff-62353cc2644f', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '6ea152ad-9b82-4f18-9b90-23c3246e18e8', 'subtopic'::public.curated_course_node_type, 'Religious literacy', 'Students practice accurate, respectful, and critical explanation of traditions without stereotyping or flattening difference.', 2),
  ('d872f951-663c-4bc1-a591-09e09c5dd961', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'adfa65a6-1228-496f-90ff-62353cc2644f', 'concept'::public.curated_course_node_type, 'Basic vocabulary', null, 0),
  ('202eedbf-40ae-4075-a621-322cb7725815', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'adfa65a6-1228-496f-90ff-62353cc2644f', 'concept'::public.curated_course_node_type, 'Avoiding essentialism', null, 1),
  ('79cb4fab-c598-42e7-943e-c7b54792b9c2', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'adfa65a6-1228-496f-90ff-62353cc2644f', 'concept'::public.curated_course_node_type, 'Public consequences of religious ignorance', null, 2),
  ('c2cdc9fa-73bd-48d8-a9df-4330da3560ec', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', null, 'topic'::public.curated_course_node_type, 'Defining Religion: The Sacred, Lived Religion, and Critical Categories', 'Definitions of religion are tools, not neutral facts. This section helps students understand why definitions matter, what they reveal, and what they obscure.', 1),
  ('1818a6e5-5fe5-485e-9a9a-b81245e4f515', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'c2cdc9fa-73bd-48d8-a9df-4330da3560ec', 'subtopic'::public.curated_course_node_type, 'Substantive and functional definitions', 'Students compare definitions that focus on gods, sacred realities, ultimate concern, social cohesion, experience, or practice.', 0),
  ('834f4eac-d579-4d2e-9920-a85bd1e02604', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '1818a6e5-5fe5-485e-9a9a-b81245e4f515', 'concept'::public.curated_course_node_type, 'Sacred/profane', null, 0),
  ('5046cd6a-9553-4bf5-87ab-f25df7e828cf', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '1818a6e5-5fe5-485e-9a9a-b81245e4f515', 'concept'::public.curated_course_node_type, 'Ultimate concern', null, 1),
  ('dcc5be8d-0511-44ff-b4e4-6094e7ef1a62', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '1818a6e5-5fe5-485e-9a9a-b81245e4f515', 'concept'::public.curated_course_node_type, 'Social function', null, 2),
  ('9cd07bd0-444d-4440-8df3-8bb26baed34c', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'c2cdc9fa-73bd-48d8-a9df-4330da3560ec', 'subtopic'::public.curated_course_node_type, 'Lived religion', 'This approach shifts attention from official doctrine to what people actually do in homes, streets, bodies, calendars, and online spaces.', 1),
  ('59075ddd-b664-423b-b169-fcbef9ae4291', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '9cd07bd0-444d-4440-8df3-8bb26baed34c', 'concept'::public.curated_course_node_type, 'Everyday practice', null, 0),
  ('36964ca6-21b2-46e1-bc3e-46691380e67b', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '9cd07bd0-444d-4440-8df3-8bb26baed34c', 'concept'::public.curated_course_node_type, 'Domestic religion', null, 1),
  ('de1a0c2d-8801-4e93-bc02-a2e783b7e651', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '9cd07bd0-444d-4440-8df3-8bb26baed34c', 'concept'::public.curated_course_node_type, 'Popular religion', null, 2),
  ('590f9e0d-4ee2-4f6b-817e-4530d5af2c29', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'c2cdc9fa-73bd-48d8-a9df-4330da3560ec', 'subtopic'::public.curated_course_node_type, 'Category critique', 'Students ask who invented categories, who benefits from them, and how colonial, legal, or academic classification shapes what counts as religion.', 2),
