  ('5f60d820-5613-4601-84be-620c408b83ce', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '590f9e0d-4ee2-4f6b-817e-4530d5af2c29', 'concept'::public.curated_course_node_type, 'Race and empire', null, 1),
  ('12860c53-6889-4123-8e75-7aa3db3d333a', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '590f9e0d-4ee2-4f6b-817e-4530d5af2c29', 'concept'::public.curated_course_node_type, 'Religion vs. culture', null, 2),
