  ('0b2004a7-5083-47d0-90d6-2be10fd922f5', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '3c5f0270-5ced-423e-bfca-c97a98079426', 'subtopic'::public.curated_course_node_type, 'Textual and historical methods', 'Students learn to read sources in context, identify genre, track transmission, and distinguish primary from secondary evidence.', 0),
  ('f03eeb00-7d0e-4489-9a3a-a990b46ea89b', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '0b2004a7-5083-47d0-90d6-2be10fd922f5', 'concept'::public.curated_course_node_type, 'Authorship and audience', null, 0),
  ('2666c3e2-2a32-4e21-887a-a93ce20c1c7c', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '0b2004a7-5083-47d0-90d6-2be10fd922f5', 'concept'::public.curated_course_node_type, 'Canon and commentary', null, 1),
  ('29778195-7185-46c6-9105-1066f5d037a8', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '0b2004a7-5083-47d0-90d6-2be10fd922f5', 'concept'::public.curated_course_node_type, 'Historical-critical questions', null, 2),
  ('a030d526-1773-4848-88d4-2f986060292b', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '3c5f0270-5ced-423e-bfca-c97a98079426', 'subtopic'::public.curated_course_node_type, 'Ethnography and field observation', 'Students learn how interviews, observation, fieldnotes, and reflexivity help scholars study living communities responsibly.', 1),
