  ('8c7d4176-83e6-4c81-86c9-98a4acfb6cd9', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'a030d526-1773-4848-88d4-2f986060292b', 'concept'::public.curated_course_node_type, 'Thick description', null, 2),
  ('789424ab-e2f4-45e7-9c1a-fd180cc2cd2e', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '3c5f0270-5ced-423e-bfca-c97a98079426', 'subtopic'::public.curated_course_node_type, 'Material and digital religion', 'Students treat objects, architecture, sound, images, apps, and online communities as evidence rather than decoration.', 2),
