  ('75447d4c-2841-4212-b85c-6bb070335a7d', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '789424ab-e2f4-45e7-9c1a-fd180cc2cd2e', 'concept'::public.curated_course_node_type, 'Digital rituals', null, 1),
  ('f3471345-b1f2-4880-abfd-edd45379d58c', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '789424ab-e2f4-45e7-9c1a-fd180cc2cd2e', 'concept'::public.curated_course_node_type, 'Archives and metadata', null, 2),
  ('bffd6340-832c-4d82-9d5a-c1f0a61714a6', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', null, 'topic'::public.curated_course_node_type, 'Myth, Narrative, Scripture, and Interpretation', 'Stories and texts do religious work: they organize memory, authority, ethics, identity, and time. This section trains students to interpret them carefully.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('1fb86d70-a485-4aea-b91b-a9b6a0357479', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'bffd6340-832c-4d82-9d5a-c1f0a61714a6', 'subtopic'::public.curated_course_node_type, 'Myth and sacred narrative', 'Students learn that myth is not simply falsehood; in religious studies it often names meaningful narrative that structures a world.', 0),
