  ('f08d8e79-eaa8-447e-8db2-ac356a9c4a03', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '157fb6a0-5f6e-4146-ae98-929572b8a0fc', 'concept'::public.curated_course_node_type, 'Interpretive conflict', null, 2),
