  ('3e2f5a51-c175-4ba2-83eb-c9fb1297109d', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '50c2ab8b-ae2f-469c-9a9a-ac8679d43d00', 'concept'::public.curated_course_node_type, 'Gendered bodies', null, 2),
