  ('c1d03d81-c43d-42e6-b7d1-207296c47f51', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '8f50b07d-a426-4648-a975-f9d7068333e2', 'concept'::public.curated_course_node_type, 'Psychology and culture', null, 2),
  ('ff783fdb-9241-4fd6-b0c6-7d02315bb183', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', null, 'topic'::public.curated_course_node_type, 'Symbol, Image, Sound, Space, and Material Culture', 'Material culture shows how religion becomes visible, audible, tangible, and contested. Students learn to analyze things and spaces as arguments about value and authority.', 5),
  ('1835dafa-baee-4205-b22d-a64af4f8113a', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'ff783fdb-9241-4fd6-b0c6-7d02315bb183', 'subtopic'::public.curated_course_node_type, 'Symbols and images', 'Students ask how signs, icons, clothing, colors, and visual forms condense complex meanings.', 0),
  ('9e12e7ba-0df4-4c37-bd5e-e6d602bad06f', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '1835dafa-baee-4205-b22d-a64af4f8113a', 'concept'::public.curated_course_node_type, 'Icon and iconoclasm', null, 0),
  ('1a7d977b-e689-49c4-97da-5b3a2f1f8fb1', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '1835dafa-baee-4205-b22d-a64af4f8113a', 'concept'::public.curated_course_node_type, 'Dress and identity', null, 1),
  ('33ceba4a-2b0b-4df7-942a-aca1a1e76dbf', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '1835dafa-baee-4205-b22d-a64af4f8113a', 'concept'::public.curated_course_node_type, 'Art and devotion', null, 2),
  ('26e3e1a6-6732-4d50-ad49-d0171dd51922', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'ff783fdb-9241-4fd6-b0c6-7d02315bb183', 'subtopic'::public.curated_course_node_type, 'Sacred space', 'Students analyze temples, churches, mosques, synagogues, shrines, homes, landscapes, memorials, and digital spaces.', 1),
  ('5d5ba2bf-297a-4650-a90c-88b85ef57d32', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '26e3e1a6-6732-4d50-ad49-d0171dd51922', 'concept'::public.curated_course_node_type, 'Architecture', null, 0),
  ('bdbb82d8-a372-40c9-9344-c6503228f0d8', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '26e3e1a6-6732-4d50-ad49-d0171dd51922', 'concept'::public.curated_course_node_type, 'Pilgrimage sites', null, 1),
  ('b0e5c620-33e9-4973-8879-8e361ce51657', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '26e3e1a6-6732-4d50-ad49-d0171dd51922', 'concept'::public.curated_course_node_type, 'Place-making', null, 2),
  ('6c917a16-cc58-4b8a-808c-500f4f27d0a0', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'ff783fdb-9241-4fd6-b0c6-7d02315bb183', 'subtopic'::public.curated_course_node_type, 'Sound, food, and objects', 'The goal is to notice how music, chant, bells, foodways, relics, tools, and commodities carry religious meaning.', 2),
  ('f0feac86-5ecb-41a9-a769-decb90dfd8f7', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '6c917a16-cc58-4b8a-808c-500f4f27d0a0', 'concept'::public.curated_course_node_type, 'Music and chant', null, 0),
  ('54fd6bf8-e2e5-492d-ba64-cb775747be92', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '6c917a16-cc58-4b8a-808c-500f4f27d0a0', 'concept'::public.curated_course_node_type, 'Food laws', null, 1),
  ('53c887b8-9f51-4b16-802b-a7194a65e4fb', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '6c917a16-cc58-4b8a-808c-500f4f27d0a0', 'concept'::public.curated_course_node_type, 'Relics and commodities', null, 2),
  ('fadfc15e-b9a7-4c7c-b90a-ebf033e8c4de', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', null, 'topic'::public.curated_course_node_type, 'Community, Authority, Institutions, and Tradition-Making', 'Traditions are maintained and changed by communities. This section studies leadership, law, lineage, institutions, memory, reform, and conflict.', 6),
  ('05034e21-eae1-427c-8ac2-cafadd9ef564', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'fadfc15e-b9a7-4c7c-b90a-ebf033e8c4de', 'subtopic'::public.curated_course_node_type, 'Authority and leadership', 'Students examine how authority is justified through charisma, office, scripture, lineage, expertise, revelation, or community recognition.', 0);
