  ('cd68e5c9-f0b0-48d5-bb7f-4ece4cea3eb2', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'fadfc15e-b9a7-4c7c-b90a-ebf033e8c4de', 'subtopic'::public.curated_course_node_type, 'Continuity and change', 'The section frames reform, revival, schism, syncretism, and innovation as normal parts of religious history.', 2),
  ('6a8f99c1-81cb-4711-a347-f2c00ceaf0cb', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'cd68e5c9-f0b0-48d5-bb7f-4ece4cea3eb2', 'concept'::public.curated_course_node_type, 'Reform movements', null, 0),
  ('0217a951-7038-4f57-8462-d051e8f835a4', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'cd68e5c9-f0b0-48d5-bb7f-4ece4cea3eb2', 'concept'::public.curated_course_node_type, 'Sect and denomination', null, 1),
  ('b2635ebb-cc7e-4d8a-9a4a-cc09d469d5a3', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'cd68e5c9-f0b0-48d5-bb7f-4ece4cea3eb2', 'concept'::public.curated_course_node_type, 'Memory and invention', null, 2),
  ('cc3bd060-669d-43ea-b856-58a1ef52f2d2', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', null, 'topic'::public.curated_course_node_type, 'Comparison, Translation, Classification, and World Religions', 'Comparison is powerful but risky. Students learn to compare responsibly, recognize the limits of the world religions model, and avoid false equivalence.', 7),
