  ('f79db83c-364c-4e9e-a1e8-dadc6639fc77', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'a06a9bdf-c7cc-43e9-915e-0056397d3e8f', 'concept'::public.curated_course_node_type, 'Controlled comparison', null, 0),
  ('0a5bd0a2-9be6-4bad-ae45-ea5261043e9b', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'a06a9bdf-c7cc-43e9-915e-0056397d3e8f', 'concept'::public.curated_course_node_type, 'Difference and similarity', null, 1),
  ('f879deac-ea06-42e2-9612-044fb6a44b83', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'a06a9bdf-c7cc-43e9-915e-0056397d3e8f', 'concept'::public.curated_course_node_type, 'Scale of analysis', null, 2),
  ('76209bdf-4688-41ba-9cef-eea257091a9f', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'cc3bd060-669d-43ea-b856-58a1ef52f2d2', 'subtopic'::public.curated_course_node_type, 'Translation problems', 'Students explore why terms such as religion, scripture, god, ritual, caste, dharma, and secular do not map cleanly across languages.', 1),
  ('d5294f87-f7a6-4fe8-8414-a61e0b89f5fa', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '76209bdf-4688-41ba-9cef-eea257091a9f', 'concept'::public.curated_course_node_type, 'Untranslatable terms', null, 0),
  ('38a9bd38-110d-48be-8171-956f5c7a07b3', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '76209bdf-4688-41ba-9cef-eea257091a9f', 'concept'::public.curated_course_node_type, 'Colonial translation', null, 1),
  ('f87acc64-6f7d-4daf-9286-342b0a2fd21c', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '76209bdf-4688-41ba-9cef-eea257091a9f', 'concept'::public.curated_course_node_type, 'Conceptual humility', null, 2),
  ('38931215-39d8-463b-bdcc-9349cbbb68af', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'cc3bd060-669d-43ea-b856-58a1ef52f2d2', 'subtopic'::public.curated_course_node_type, 'Classification and power', 'The section asks how museum labels, census categories, law, textbooks, and media shape public understanding.', 2),
  ('dbe5febf-d2c3-4e65-8efc-4c527dcac80b', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '38931215-39d8-463b-bdcc-9349cbbb68af', 'concept'::public.curated_course_node_type, 'World religions textbooks', null, 0),
  ('862ff9d0-d566-4cf6-995b-c8e0f267a068', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '38931215-39d8-463b-bdcc-9349cbbb68af', 'concept'::public.curated_course_node_type, 'Legal definitions', null, 1),
  ('a8afd787-4b44-4d99-bf1f-5f2b3c12d87d', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '38931215-39d8-463b-bdcc-9349cbbb68af', 'concept'::public.curated_course_node_type, 'Minority traditions', null, 2),
