  ('d864d6aa-b3ba-4640-b488-7fd6316ab4f1', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'e397c500-9e30-4ea3-a1b6-9ce4d408e646', 'concept'::public.curated_course_node_type, 'Oral tradition', null, 0),
  ('6de7d96b-159f-48cf-b394-e2cbe1c10a1c', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'e397c500-9e30-4ea3-a1b6-9ce4d408e646', 'concept'::public.curated_course_node_type, 'Sacred landscapes', null, 1),
  ('8f34bb33-e597-45d2-8afe-763665ff2d09', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'e397c500-9e30-4ea3-a1b6-9ce4d408e646', 'concept'::public.curated_course_node_type, 'Colonial disruption', null, 2),
  ('be50cc96-c736-4e84-b43e-defec740179b', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '105b29dd-293f-408b-8001-c1abd045bf2d', 'subtopic'::public.curated_course_node_type, 'Diaspora and migration', 'Students study how religious communities adapt across borders while preserving memory, ritual, and identity.', 1),
  ('e95d49f9-dd32-4e86-944e-ba2d94a81739', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'be50cc96-c736-4e84-b43e-defec740179b', 'concept'::public.curated_course_node_type, 'Temples and community centers', null, 0),
