  ('38693969-cc62-4e2c-870f-878b99f85ab3', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '2b50ac68-c576-48e9-984d-54570e654300', 'concept'::public.curated_course_node_type, 'Household shrines', null, 0),
  ('1a171277-9004-45dd-9c91-cba9dcbe28f9', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', '2b50ac68-c576-48e9-984d-54570e654300', 'concept'::public.curated_course_node_type, 'Festivals', null, 1),
