  ('c8f840f2-87c1-4aed-b6f9-996936a23651', 'f8a9b0c1-2d3e-4f33-8c23-3a4b5c6d7e63', 'c0a1ead9-ef46-4e20-a5fd-433e33a8e0a5', 'subtopic'::public.curated_course_node_type, 'South Asian traditions', 'Students encounter Hindu, Buddhist, Jain, and Sikh traditions through ritual, philosophy, devotion, caste, renunciation, and modernity.', 0),
